{"path":"about.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>About — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#0f1720;--card:#0b1220;--accent:#66d9a8;--muted:#9aa6b2;--glass:rgba(255,255,255,0.04)}
    html,body{height:100%;margin:0;font-family:Inter,system-ui,-apple-system,Segoe UI,Roboto,"Helvetica Neue",Arial;color:#e6eef6;background:linear-gradient(180deg,#07101a 0%,#07121a 40%),var(--bg);}
    a{color:var(--accent);text-decoration:none}
    header{display:flex;align-items:center;justify-content:space-between;padding:20px 28px;background:linear-gradient(90deg,rgba(255,255,255,0.02),transparent);backdrop-filter:blur(6px)}
    .logo{font-weight:700;letter-spacing:0.6px}
    nav a{margin:0 10px;font-size:14px;color:var(--muted)}
    .wrap{max-width:980px;margin:34px auto;padding:32px;background:linear-gradient(180deg,rgba(255,255,255,0.02),transparent);border-radius:12px;box-shadow:0 8px 30px rgba(2,6,23,0.7)}

    .hero{display:grid;grid-template-columns:1fr 340px;gap:28px;align-items:center}
    .hero h1{margin:0;font-size:34px;color:#fff}
    .hero p{color:var(--muted);line-height:1.6}
    .card{background:var(--card);padding:18px;border-radius:10px}
    .small{font-size:13px;color:var(--muted)}

    /* Proof Gallery */
    .proof{margin-top:22px;display:flex;gap:16px;align-items:flex-start}
    .testi{flex:1;padding:18px;border-radius:10px;background:linear-gradient(180deg,rgba(255,255,255,0.01),transparent);min-height:120px}
    .testi p{margin:0;color:#eaf8f2;font-size:15px}
    .by{margin-top:10px;color:var(--muted);font-size:13px}
    .badges{display:flex;gap:8px;margin-top:12px}
    .badge{background:var(--glass);padding:6px 10px;border-radius:8px;font-size:13px;color:var(--muted);display:inline-flex;align-items:center;gap:8px;position:relative}
    .badge svg{width:16px;height:16px;fill:var(--accent)}
    .tt{position:absolute;left:50%;transform:translateX(-50%) translateY(-8px);top:-42px;background:#041021;padding:8px;border-radius:6px;font-size:12px;color:#cfeee0;white-space:nowrap;opacity:0;pointer-events:none;transition:opacity .15s}
    .badge:hover .tt{opacity:1}

    .grid{display:grid;grid-template-columns:repeat(2,1fr);gap:18px;margin-top:20px}

    /* CTA */
    .cta{display:flex;gap:14px;align-items:center;margin-top:18px}
    .btn{background:linear-gradient(90deg,var(--accent),#31b98f);color:#04201a;padding:12px 16px;border-radius:10px;font-weight:600;border:none;cursor:pointer}
    .ghost{background:transparent;border:1px solid rgba(255,255,255,0.06);color:var(--muted);padding:10px 14px;border-radius:10px}

    footer{padding:18px;text-align:center;color:var(--muted);font-size:13px;margin-top:18px}

    /* decorative pattern top-right */
    .pattern{position:absolute;right:24px;top:40px;width:160px;height:160px;opacity:0.12}
  </style>
</head>
<body>
  <svg class="pattern" viewBox="0 0 200 200" xmlns="http://www.w3.org/2000/svg" aria-hidden>
    <defs>
      <linearGradient id="g1" x1="0" x2="1">
        <stop offset="0" stop-color="#5be1b3" stop-opacity="0.9" />
        <stop offset="1" stop-color="#47c3a1" stop-opacity="0.6" />
      </linearGradient>
    </defs>
    <rect x="0" y="0" width="200" height="200" rx="28" fill="url(#g1)" />
    <g fill="#052126" fill-opacity="0.12">
      <circle cx="40" cy="40" r="18" />
      <circle cx="120" cy="70" r="8" />
      <rect x="70" y="110" width="62" height="12" rx="6" />
    </g>
  </svg>

  <header>
    <div class="logo">{{BUSINESS_NAME}}</div>
    <nav>
      <a href="index.html">Home</a>
      <a href="about.html">Studio</a>
      <a href="services.html">Offerings</a>
      <a href="programs.html">Journeys</a>
      <a href="pricing.html">Rates</a>
      <a href="testimonials.html">Stories</a>
      <a href="book.html">Reserve</a>
      <a href="contact.html">Connect</a>
    </nav>
  </header>

  <main class="wrap">
    <section class="hero">
      <div>
        <h1>Slow maps and steady practices — a modern guide for steady energy.</h1>
        <p class="small">I design reliable routines, shape daily habits that stick, and translate intentions into simple frameworks you can use every morning and night. No prescriptions—only practical structure and outcomes you can test and repeat.</p>

        <div class="grid">
          <div class="card">
            <strong>What you gain</strong>
            <p class="small">Tools to shape an hour, a day, and repeated behaviors that outlast motivation.</p>
          </div>
          <div class="card">
            <strong>How we work</strong>
            <p class="small">Bite-sized experiments, clear metrics, and weekly reflection—so shifts become habits.</p>
          </div>
        </div>

        <div class="cta">
          <button class="btn" onclick="location.href='book.html'">Start a discovery call</button>
          <a class="ghost" href="contact.html">Ask a quick question</a>
        </div>
      </div>

      <aside class="card">
        <div class="small">Quick profile</div>
        <h3 style="margin:8px 0 0 0;color:#eafff3">A coach for practical change</h3>
        <p class="small" style="margin-top:8px">Sessions weave habit design, outcome-setting, and a compact practice plan you can run each day.</p>
        <div style="margin-top:12px">
          <div class="small">Contact</div>
          <div style="margin-top:6px"><a href="tel:{{PHONE}}">{{PHONE}}</a> • <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></div>
        </div>
      </aside>
    </section>

    <section style="margin-top:22px">
      <h3 style="color:#eafaf0">Proof Gallery</h3>
      <div class="proof">
        <div class="testi" id="rotTestimonial">
          <p id="quote">Creating a small evening ritual changed the way I start the next day—simple and dependable.</p>
          <div class="by" id="author">— L. in {{CITY}}, {{STATE}}</div>
          <div class="badges" id="badges">
            <div class="badge" data-tooltip="Featured in local wellness newsletter">
              <svg viewBox="0 0 24 24" xmlns="http://www.w3.org/2000/svg"><path d="M12 2L15 8l6 .5-4.5 3.5L18 20l-6-3.5L6 20l1.5-8L3 8.5 9 8 12 2z"/></svg>
              Press
              <div class="tt">Local feature: Mindful City</div>
            </div>
            <div class="badge" data-tooltip="Accredited coach program">
              <svg viewBox="0 0 24 24" xmlns="http://www.w3.org/2000/svg"><circle cx="12" cy="8" r="3"/><path d="M5 20c1.5-3 4-5 7-5s5.5 2 7 5"/></svg>
              Certification
              <div class="tt">Certified Coach Network</div>
            </div>
            <div class="badge" data-tooltip="Corporate wellness partner">
              <svg viewBox="0 0 24 24" xmlns="http://www.w3.org/2000/svg"><rect x="3" y="3" width="18" height="18" rx="3"/></svg>
              Partner
              <div class="tt">Wellness Collective</div>
            </div>
          </div>
        </div>

        <div style="width:260px">
          <div class="card">
            <div class="small">Rotation speed</div>
            <input id="speed" type="range" min="3000" max="15000" step="1000" value="6000" style="width:100%" />
            <div class="small" style="margin-top:10px">Tip: hover badges for more context.</div>
          </div>
        </div>
      </div>
    </section>

    <section style="margin-top:22px">
      <h3 style="color:#eafaf0">What to expect</h3>
      <div class="grid">
        <div class="card">
          <strong>Week 1 — Tiny experiments</strong>
          <p class="small">We test small shifts you can keep for a week. Data, feeling, and adjustments follow.</p>
        </div>
        <div class="card">
          <strong>Month 1 — Anchor routines</strong>
          <p class="small">We build a scaffold that supports the changes. Each element has a clear purpose.</p>
        </div>
      </div>
    </section>

    <section style="margin-top:22px">
      <h3 style="color:#eafaf0">Common hesitations</h3>
      <div class="grid">
        <div class="card">
          <strong>Too busy</strong>
          <p class="small">I start with five-minute practices and scale only when you notice benefit.</p>
        </div>
        <div class="card">
          <strong>Does it fit my life?</strong>
          <p class="small">Frameworks are adapted for routines you already have—no wholesale rewiring required.</p>
        </div>
      </div>
    </section>

    <section style="margin-top:24px;display:flex;gap:12px;align-items:center;justify-content:space-between">
      <div>
        <h3 style="margin:0;color:#eafff3">Ready to try a short strategy session?</h3>
        <div class="small">A focused hour to learn one repeatable practice and a path to keep it.</div>
      </div>
      <div>
        <button class="btn" onclick="location.href='book.html'">Book your strategy hour</button>
      </div>
    </section>

  </main>

  <footer>
    <div>Questions? <a href="mailto:{{EMAIL}}">{{EMAIL}}</a> • <a href="tel:{{PHONE}}">{{PHONE}}</a></div>
    <div style="margin-top:6px">© <span id="year"></span> {{BUSINESS_NAME}}</div>
  </footer>

  <script>
    // Proof Gallery rotation
    (function(){
      const quotes = [
        {q: 'I now have a 10-minute practice that actually resets my morning.', a: '— A. in {{CITY}}, {{STATE}}'},
        {q: 'Small weekly experiments took the guesswork out of routines.', a: '— R. in {{CITY}}, {{STATE}}'},
        {q: 'Clear checkpoints and a tiny plan turned into steady momentum.', a: '— S. in {{CITY}}, {{STATE}}'}
      ];
      let idx=0;const elQ=document.getElementById('quote');const elA=document.getElementById('author');
      const speedInput=document.getElementById('speed');
      let delay=+speedInput.value;let timer;
      function show(i){elQ.style.opacity=0;elA.style.opacity=0;setTimeout(()=>{elQ.textContent=quotes[i].q;elA.textContent=quotes[i].a;elQ.style.opacity=1;elA.style.opacity=1;},180)}
      function loop(){idx=(idx+1)%quotes.length;show(idx);timer=setTimeout(loop,delay);} 
      speedInput.addEventListener('input',e=>{delay=+e.target.value;clearTimeout(timer);timer=setTimeout(loop,delay);});
      show(0);timer=setTimeout(loop,delay);
    })();

    // Footer year
    document.getElementById('year').textContent=new Date().getFullYear();
  </script>
</body>
</html>"} 
{"path":"services.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Offerings — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#07121a;--card:#081622;--accent:#9be7c9;--muted:#9fb2bb}
    body{margin:0;font-family:Inter,system-ui,-apple-system,Segoe UI,Roboto,Arial;background:radial-gradient(1200px 600px at 10% 10%,rgba(155,231,201,0.06),transparent),var(--bg);color:#e7fbf1}
    header{display:flex;justify-content:space-between;align-items:center;padding:18px 28px}
    .logo{font-weight:700}
    nav a{margin:0 10px;color:var(--muted);font-size:14px}
    .container{max-width:1000px;margin:28px auto;padding:20px}
    .hero{display:flex;align-items:center;justify-content:space-between;gap:20px}
    h1{margin:0;font-size:30px}
    .lead{color:var(--muted);max-width:600px}

    .services{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin-top:18px}
    .svc{background:linear-gradient(180deg,rgba(255,255,255,0.01),transparent);padding:14px;border-radius:10px}
