    .toggle button{border:0;background:transparent;color:var(--muted);padding:6px 10px;border-radius:999px;cursor:pointer}
    .toggle button.active{background:linear-gradient(90deg,var(--accent),#55caa7);color:#042124}
    .price-row{display:flex;justify-content:space-between;align-items:center;padding:12px 6px}
    .price-anim{font-size:22px;font-weight:800}

    .note{font-size:13px;color:var(--muted);margin-top:8px}
  </style>
</head>
<body>
  <header>
    <div class="logo">{{BUSINESS_NAME}}</div>
    <nav>
      <a href="index.html">Home</a>
      <a href="about.html">About</a>
      <a href="services.html">Offerings</a>
      <a href="programs.html">Paths</a>
      <a href="pricing.html">Pricing</a>
      <a href="testimonials.html">Voices</a>
      <a href="book.html">Book</a>
      <a href="contact.html">Contact</a>
    </nav>
  </header>

  <main class="container">
    <section class="hero">
      <div>
        <h1>Offerings tuned for steady progress</h1>
        <p class="lead">Short blocks and repeatable sessions that help you build a dependable daily practice—outcomes first, then habit architecture.</p>
      </div>
      <div style="text-align:right">
        <div class="small" style="color:var(--muted)">Quick connect</div>
        <div style="margin-top:8px"><a style="color:var(--accent)" href="mailto:{{EMAIL}}">{{EMAIL}}</a></div>
      </div>
    </section>

    <section class="services" aria-label="services list">
      <article class="svc">
        <h4>Focus Session</h4>
        <div class="small">45-minute diagnostic and a simple morning anchor.</div>
        <div style="margin-top:10px"><span class="price">$95</span> <span class="small">single</span></div>
      </article>

      <article class="svc">
        <h4>Rhythm Workshop</h4>
        <div class="small">Two-hour class for building a compact evening routine and transition plan.</div>
        <div style="margin-top:10px"><span class="price">$180</span> <span class="small">single</span></div>
      </article>

      <article class="svc">
        <h4>Practice Architecture</h4>
        <div class="small">Four sessions to design a week-long structure and measure what matters.</div>
        <div style="margin-top:10px"><span class="price">$650</span> <span class="small">package</span></div>
      </article>
    </section>

    <section class="pricing" id="pricing">
      <div style="display:flex;justify-content:space-between;align-items:center">
        <div>
          <h3 style="margin:0">Compare commitment</h3>
          <div class="note">Toggle between monthly subscriptions and one-off packages. Prices animate for clarity.</div>
        </div>
        <div class="toggle" role="tablist" aria-label="Pricing toggle">
          <button id="opt-package" class="active" aria-pressed="true">Package</button>
          <button id="opt-month">Monthly</button>
        </div>
      </div>

      <div style="margin-top:12px">
        <div class="price-row"><div>Focus Session</div><div class="price-anim" data-pkg="95" data-mon="30">$95</div></div>
        <div class="price-row"><div>Rhythm Workshop</div><div class="price-anim" data-pkg="180" data-mon="55">$180</div></div>
        <div class="price-row"><div>Practice Architecture</div><div class="price-anim" data-pkg="650" data-mon="120">$650</div></div>
      </div>
      <div class="note">Monthly option billed as ongoing support; package is a limited engagement.</div>
    </section>

    <section style="margin-top:18px">
      <h3 style="margin:0">Ready to try one?</h3>
      <div class="note">Choose a single session to test a habit, or commit to a package for measurable change.</div>
      <div style="margin-top:12px">
        <button class="btn" onclick="location.href='book.html'" style="background:linear-gradient(90deg,var(--accent),#67d3b4);border:0;padding:10px 14px;border-radius:8px;font-weight:700;color:#04221d">Reserve a session</button>
      </div>
    </section>
  </main>

  <script>
    // Pricing comparator with animated numbers
    (function(){
      const btnPkg=document.getElementById('opt-package');
      const btnMon=document.getElementById('opt-month');
      const priceEls=Array.from(document.querySelectorAll('.price-anim'));
      let mode='pkg';

      function animate(el, from, to){
        const duration=480;const start=performance.now();
        function step(now){
          const t=Math.min(1,(now-start)/duration);
          const val=Math.round(from+(to-from)*t);
          el.textContent = '$'+val;
          if(t<1) requestAnimationFrame(step);
        }
        requestAnimationFrame(step);
      }

      function setMode(m){
        mode=m;
        if(mode==='pkg'){btnPkg.classList.add('active');btnPkg.setAttribute('aria-pressed','true');btnMon.classList.remove('active');btnMon.setAttribute('aria-pressed','false');}
        else {btnMon.classList.add('active');btnMon.setAttribute('aria-pressed','true');btnPkg.classList.remove('active');btnPkg.setAttribute('aria-pressed','false');}
        priceEls.forEach(el=>{
          const from = parseInt(el.textContent.replace('$','')) || 0;
          const to = parseInt(el.dataset[mode==='pkg' ? 'pkg' : 'mon']);
          animate(el, from, to);
        });
      }

      btnPkg.addEventListener('click',()=>setMode('pkg'));
      btnMon.addEventListener('click',()=>setMode('mon'));

      // init
      setMode('pkg');
    })();
  </script>
</body>
</html>"} 
{"path":"programs.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Journeys — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#071417;--panel:#081a1a;--accent:#6ef0d0;--muted:#9dc7bf}
    body{margin:0;font-family:Inter,system-ui,-apple-system,Segoe UI,Roboto,Arial;background:linear-gradient(180deg,#061017,#05151a);color:#e8fbf5}
    header{display:flex;justify-content:space-between;align-items:center;padding:16px 22px}
    nav a{margin:0 9px;color:var(--muted);font-size:14px}
    .wrap{max-width:1000px;margin:28px auto;padding:18px}
    h1{margin:0 0 6px 0}
    .intro{color:var(--muted);margin-bottom:16px}
    .list{display:grid;grid-template-columns:1fr 1fr;gap:14px}
    .prog{background:linear-gradient(180deg,rgba(255,255,255,0.02),transparent);padding:14px;border-radius:12px}
    .prog h4{margin:0}
    .prog .meta{color:var(--muted);font-size:13px;margin-top:8px}

    /* small comparator inside programs */
    .mini-toggle{display:inline-flex;background:rgba(255,255,255,0.03);border-radius:999px;padding:4px}
    .mini-toggle button{background:transparent;border:0;color:var(--muted);padding:6px 8px;border-radius:999px;cursor:pointer}
    .mini-toggle button.on{background:linear-gradient(90deg,var(--accent),#4fdabf);color:#052423}

    /* Proof Gallery compact */
    .proof-compact{display:flex;gap:12px;align-items:center;margin-top:18px}
    .avatar{width:52px;height:52px;border-radius:10px;background:linear-gradient(90deg,var(--accent),#4fdabf);display:inline-flex;align-items:center;justify-content:center;color:#052423;font-weight:700}
    .tcol{color:var(--muted)}

    .cta{margin-top:18px}
  </style>
</head>
<body>
  <header>
    <div class="logo">{{BUSINESS_NAME}}</div>
    <nav>
      <a href="index.html">Main</a>
      <a href="about.html">Who I am</a>
      <a href="services.html">Offerings</a>
      <a href="programs.html">Journeys</a>
      <a href="pricing.html">Fees</a>
      <a href="testimonials.html">Reviews</a>
      <a href="book.html">Schedule</a>
      <a href="contact.html">Hello</a>
    </nav>
  </header>

  <main class="wrap">
    <h1>Journeys — practical programs to build resilient routines</h1>
    <p class="intro">Three paths designed to meet you where your current habits are. Each path includes clear checkpoints and small, repeatable practices.</p>

    <section class="list">
      <div class="prog">
        <h4>Foundation Path — 4 weeks</h4>
        <div class="meta">A guided flow to establish two daily anchors and a weekly reflection habit.</div>
        <div style="margin-top:10px">
          <div class="mini-toggle" role="tablist" aria-label="Foundation pricing">
            <button id="f-pkg" class="on">Package</button>
            <button id="f-mon">Monthly</button>
          </div>
          <div style="margin-top:8px"><strong class="price" id="f-price">$420</strong></div>
        </div>
      </div>

      <div class="prog">
        <h4>Rhythm Labs — 8 weeks</h4>
        <div class="meta">Experiment cycles that refine what works, with habit labs and metric checkpoints.</div>
        <div style="margin-top:10px">
          <div class="mini-toggle">
            <button id="r-pkg" class="on">Package</button>
            <button id="r-mon">Monthly</button>
          </div>
          <div style="margin-top:8px"><strong class="price" id="r-price">$980</strong></div>
        </div>
      </div>

      <div class="prog">
        <h4>Bridge Program — 12 weeks</h4>
        <div class="meta">A longer scaffold to translate early wins into a stable weekly rhythm.</div>
        <div style="margin-top:10px">
          <div class="mini-toggle">
            <button id="b-pkg" class="on">Package</button>
            <button id="b-mon">Monthly</button>
          </div>
          <div style="margin-top:8px"><strong class="price" id="b-price">$1,900</strong></div>
        </div>
      </div>

      <div class="prog">
        <h4>Drop-in Clinics</h4>
        <div class="meta">Single session workshops to troubleshoot a practice or reset a routine.</div>
        <div style="margin-top:10px"><strong class="price">$80</strong></div>
      </div>
    </section>

    <section style="margin-top:18px">
      <h3 style="margin:0">Voices from the paths</h3>
      <div class="proof-compact">
        <div class="avatar">S</div>
        <div>
          <div style="color:#eafef4">"The Foundation Path made a chaotic morning repeatable."</div>
          <div class="tcol">— S., {{CITY}}</div>
        </div>
        <div style="margin-left:auto;color:var(--muted);font-size:13px">Hover badges for credentials</div>
      </div>

      <div style="margin-top:12px;display:flex;gap:8px;align-items:center">
        <div class="prog" style="flex:1">
          <div class="small">Credentials & badges</div>
          <div style="margin-top:8px;display:flex;gap:8px;align-items:center">
            <div class="badge" style="background:rgba(255,255,255,0.03);padding:8px;border-radius:8px;position:relative">Coach Network<div class="tip" style="position:absolute;top:-36px;left:50%;transform:translateX(-50%);background:#031519;padding:6px;border-radius:6px;color:#cfeee0;font-size:12px;opacity:0;transition:opacity .15s">Member since 2018</div></div>
