      function wire(pkgBtn, monBtn, el, pkgVal, monVal){
        function animate(from,to){
          const dur=380;const start=performance.now();
          function f(now){const t=Math.min(1,(now-start)/dur);const v=Math.round(from+(to-from)*t);el.textContent='$'+v; if(t<1)requestAnimationFrame(f);
          }
          requestAnimationFrame(f);
        }
        pkgBtn.addEventListener('click',()=>{pkgBtn.classList.add('on');monBtn.classList.remove('on');animate(parseInt(el.textContent.replace('$',''))||0,pkgVal)});
